<span class="line"><span style="color:#61AFEF;">nstat</span><span style="color:#D19A66;"> -az</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> TcpExtSyncookiesReceived</span></span>
