<span class="line"><span style="color:#61AFEF;">net.ipv4.tcp_max_syn_backlog</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 65535</span><span style="color:#7F848E;font-style:italic;"> # 半连接队列上限</span></span>
